pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        LogFile log = new LogFile();
        c.SetLogFile(address(log));
    }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // General rule: a depositor's recorded balance equals the Ether actually held by C.
        assertTrue(c.balances(actor) == address(c).balance);
    }
}

